package vn.hust.restaurant.repository;
import java.math.*;import java.sql.*;import java.time.*;import java.util.*;import vn.hust.restaurant.config.Database;import vn.hust.restaurant.model.Ingredient;
public class InventoryRepository{
 public record Supplier(int id,String code,String name,String phone,String email,String address,String status){public String toString(){return name+" - "+phone;}}
 public List<Ingredient> ingredients(String k)throws SQLException{List<Ingredient>o=new ArrayList<>();k=k==null?"":k;String s="""
 SELECT n.MaNL,n.MaNLCode,n.MaDanhMucNL,d.TenDanhMuc,n.TenNL,n.DonViTinh,n.SoLuongTon,n.DinhMucToiThieu,n.DonGiaNhapGanNhat,n.TrangThai
 FROM NguyenLieu n JOIN DanhMucNguyenLieu d ON d.MaDanhMucNL=n.MaDanhMucNL WHERE (?='' OR n.TenNL LIKE '%'+?+'%') ORDER BY d.TenDanhMuc,n.TenNL
 """;try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement(s)){p.setString(1,k);p.setString(2,k);try(ResultSet r=p.executeQuery()){while(r.next())o.add(new Ingredient(r.getInt(1),r.getString(2),r.getInt(3),r.getString(4),r.getString(5),r.getString(6),r.getBigDecimal(7),r.getBigDecimal(8),r.getBigDecimal(9),r.getString(10)));}}return o;}
 public Map<Integer,String> categories()throws SQLException{Map<Integer,String>m=new LinkedHashMap<>();try(Connection c=Database.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT MaDanhMucNL,TenDanhMuc FROM DanhMucNguyenLieu ORDER BY TenDanhMuc")){while(r.next())m.put(r.getInt(1),r.getString(2));}return m;}
 public void saveIngredient(Ingredient x)throws SQLException{String s=x.id()==0?"INSERT NguyenLieu(MaNLCode,MaDanhMucNL,TenNL,DonViTinh,SoLuongTon,DinhMucToiThieu,DonGiaNhapGanNhat,TrangThai) VALUES(?,?,?,?,?,?,?,'HOAT_DONG')":"UPDATE NguyenLieu SET MaNLCode=?,MaDanhMucNL=?,TenNL=?,DonViTinh=?,SoLuongTon=?,DinhMucToiThieu=?,DonGiaNhapGanNhat=?,TrangThai=? WHERE MaNL=?";try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement(s)){p.setString(1,x.code());p.setInt(2,x.categoryId());p.setString(3,x.name());p.setString(4,x.unit());p.setBigDecimal(5,x.stock());p.setBigDecimal(6,x.minimumStock());p.setBigDecimal(7,x.lastCost());if(x.id()!=0){p.setString(8,x.status());p.setInt(9,x.id());}p.executeUpdate();}}
 public List<Supplier> suppliers()throws SQLException{List<Supplier>o=new ArrayList<>();try(Connection c=Database.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT MaNCC,MaNCCCode,TenNCC,SDT,Email,DiaChi,TrangThai FROM NhaCungCap ORDER BY TenNCC")){while(r.next())o.add(new Supplier(r.getInt(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7)));}return o;}
 public void saveSupplier(Supplier x)throws SQLException{String s=x.id()==0?"INSERT NhaCungCap(MaNCCCode,TenNCC,SDT,Email,DiaChi,TrangThai) VALUES(?,?,?,?,?,'HOAT_DONG')":"UPDATE NhaCungCap SET MaNCCCode=?,TenNCC=?,SDT=?,Email=?,DiaChi=?,TrangThai=? WHERE MaNCC=?";try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement(s)){p.setString(1,x.code());p.setString(2,x.name());p.setString(3,x.phone());p.setString(4,x.email());p.setString(5,x.address());if(x.id()!=0){p.setString(6,x.status());p.setInt(7,x.id());}p.executeUpdate();}}
 public long receive(int employeeId,int supplierId,int ingredientId,BigDecimal qty,BigDecimal cost,LocalDate expiry,String note)throws SQLException{return Database.inTransaction(c->{long id;String code="PN"+System.currentTimeMillis();try(PreparedStatement p=c.prepareStatement("INSERT PhieuNhapKho(MaPhieuNhapCode,MaNhanVien,MaNCC,NgayNhap,TongTien,GhiChu,TrangThai) OUTPUT INSERTED.MaPhieuNhap VALUES(?,?,?,SYSDATETIME(),?,?,'DA_NHAP')")){p.setString(1,code);p.setInt(2,employeeId);p.setInt(3,supplierId);p.setBigDecimal(4,qty.multiply(cost));p.setString(5,note);try(ResultSet r=p.executeQuery()){r.next();id=r.getLong(1);}}try(PreparedStatement p=c.prepareStatement("INSERT ChiTietNhapKho(MaPhieuNhap,MaNL,SoLuong,DonGiaNhap,HanSuDung) VALUES(?,?,?,?,?)")){p.setLong(1,id);p.setInt(2,ingredientId);p.setBigDecimal(3,qty);p.setBigDecimal(4,cost);if(expiry==null)p.setNull(5,Types.DATE);else p.setDate(5,java.sql.Date.valueOf(expiry));p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("UPDATE NguyenLieu SET SoLuongTon=SoLuongTon+?,DonGiaNhapGanNhat=? WHERE MaNL=?")){p.setBigDecimal(1,qty);p.setBigDecimal(2,cost);p.setInt(3,ingredientId);p.executeUpdate();}return id;});}
 public void adjust(int employeeId,int ingredientId,BigDecimal delta,String reason)throws SQLException{Database.inTransaction(c->{try(PreparedStatement p=c.prepareStatement("UPDATE NguyenLieu SET SoLuongTon=SoLuongTon+? WHERE MaNL=? AND SoLuongTon+?>=0")){p.setBigDecimal(1,delta);p.setInt(2,ingredientId);p.setBigDecimal(3,delta);if(p.executeUpdate()==0)throw new SQLException("Điều chỉnh làm tồn kho âm");}try(PreparedStatement p=c.prepareStatement("INSERT DieuChinhKho(MaNL,MaNhanVien,SoLuongThayDoi,LyDo,ThoiGian) VALUES(?,?,?,?,SYSDATETIME())")){p.setInt(1,ingredientId);p.setInt(2,employeeId);p.setBigDecimal(3,delta);p.setString(4,reason);p.executeUpdate();}return null;});}
 public void saveRecipe(int menuId,int ingredientId,BigDecimal amount)throws SQLException{String s="MERGE CongThucMonAn AS t USING(SELECT ? MaMon,? MaNL) s ON t.MaMon=s.MaMon AND t.MaNL=s.MaNL WHEN MATCHED THEN UPDATE SET DinhLuong=? WHEN NOT MATCHED THEN INSERT(MaMon,MaNL,DinhLuong) VALUES(?,?,?);";try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement(s)){p.setInt(1,menuId);p.setInt(2,ingredientId);p.setBigDecimal(3,amount);p.setInt(4,menuId);p.setInt(5,ingredientId);p.setBigDecimal(6,amount);p.executeUpdate();}}
}
